using System;
using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "EveryXActionsCorruptActionEffect", menuName = "Data/Battle/Effects/Enemy/EveryXActionsCorruptAction Effect")]
public class EveryXActionsCorruptActionEffect : Effect
{
	private const string anomalyLevelEveryXActionsNameID = "AnomalyLevelEveryXActionsName";

	private const string anomalyLevelXEveryXActionsBaseID = "AnomalyLevelXEveryXActionsBase";

	private const string anomalyLevelXActionsRemainingID = "AnomalyLevelXActionsRemaining";

	[Header("State One")]
	[SerializeField]
	private int corruptAmount;

	[SerializeField]
	private OmenLogic omenLogic;

	[SerializeField]
	[HideIf("anomalyLevel")]
	private SingularityGoddessEffect singularityGoddessEffect;

	[SerializeField]
	private bool anomalyLevel;

	[Header("Description")]
	[SerializeField]
	[ShowIf("anomalyLevel")]
	private BattleAction corruptAction;

	[SerializeField]
	[ShowIf("anomalyLevel")]
	private int anomalyLevelValue;

	[NonSerialized]
	private int startingAmount;

	public int CorruptAmount => corruptAmount;

	public BattleAction CorruptAction => corruptAction;

	public override string GetEffectName()
	{
		if (anomalyLevel)
		{
			return Smart.Format(base.localizationManager.GetLocalizedString("AnomalyLevelEveryXActionsName"), anomalyLevelValue);
		}
		return base.GetEffectName();
	}

	protected override string GetLocalizedDescription()
	{
		if (anomalyLevel)
		{
			return "";
		}
		return base.GetLocalizedDescription();
	}

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string text = "";
		if (!anomalyLevel)
		{
			return Smart.Format(GetLocalizedDescription(), corruptAmount, startingAmount, amount);
		}
		return Smart.Format(base.localizationManager.GetLocalizedString("AnomalyLevelXEveryXActionsBase"), corruptAction.GetActionDescription(corruptAmount).UppercaseFirst().RemoveLastIfNotJapaneseNorKorean(), startingAmount) + "\n" + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("ReceiveCorruptionAnomalyLevelNonModified") + "\n" + Smart.Format(base.localizationManager.GetLocalizedString("AnomalyLevelXActionsRemaining"), amount);
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		startingAmount = effectAmount;
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		ActionInstance lateCurrentActionInstance = ReferenceSingleton<BattleHandler>.Instance.LateCurrentActionInstance;
		if (lateCurrentActionInstance != null && lateCurrentActionInstance.DiceOwnerEnum != 0)
		{
			return effectAmount;
		}
		UnitEffects component = effectOwner.GetComponent<UnitEffects>();
		int num = effectAmount - 1;
		if (num == 0)
		{
			SpawnVFX(GetVFXOwnerPosition(effectOwner), 5f);
			PlayEffectActivationSFX();
			if (anomalyLevel)
			{
				component.RemoveEffect(this, activateFeedback: false);
				component.AddEffect(this, startingAmount);
			}
			else if (singularityGoddessEffect.StateOne && !singularityGoddessEffect.ChangingAstreaState)
			{
				component.RemoveEffect(this, activateFeedback: false);
				component.AddEffect(this, startingAmount);
			}
			omenLogic.ActivateOmen(null, corruptAmount, null, effectOwner, anomalyLevel ? CorruptionPurifyModifierEnum.ANOMALY : CorruptionPurifyModifierEnum.NONE);
		}
		else
		{
			component.IsEffectActiveAndDecreaseEffect(this, 1);
		}
		if (num == 1)
		{
			component.IsEffectActiveGetEffectInstance(this).PlayBlinkingFeedback();
		}
		return effectAmount;
	}
}
